const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const groups=[['all','ทั้งหมด','#256958'],['noise','เสียงรบกวน','#d69c45'],['parking','จอดรถ / จราจร','#648bb5'],['sanitation','ขยะ / ความสะอาด','#9b81b3'],['housing','อาคาร / ที่พัก','#c97769'],['other','อื่น ๆ','#6e9c84']];
function category(r){const s=(r.complaint_type||'').toLowerCase();return /noise/.test(s)?'noise':/parking|vehicle|driveway|traffic/.test(s)?'parking':/sanitation|dirty|waste|garbage|rodent|sweeping/.test(s)?'sanitation':/heat|water|building|plumb|paint|electric|door|elevator/.test(s)?'housing':'other'}
const color=r=>groups.find(g=>g[0]===category(r))[2];let data=[],filtered=[],active='all',visible=40,markers=new Map(),selected=null;
const map=L.map('map',{zoomControl:false,preferCanvas:true}).setView([40.725,-73.94],11);L.control.zoom({position:'bottomright'}).addTo(map);const tiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',maxZoom:19}).addTo(map);tiles.on('tileerror',()=>{$('tile-error').hidden=false});tiles.on('tileload',()=>{$('tile-error').hidden=true});const layer=L.layerGroup().addTo(map);
function options(){for(const [id,key] of [['borough','borough'],['status','status']]){let prev=$(id).value;$(id).innerHTML='<option value="">'+(id==='borough'?'ทุกเขต':'ทุกสถานะ')+'</option>'+[...new Set(data.map(r=>r[key]).filter(Boolean))].sort().map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('');$(id).value=prev}}
function render(){visible=40;selected=null;$('detail').hidden=true;let q=$('search').value.trim().toLowerCase();filtered=data.filter(r=>(active==='all'||category(r)===active)&&(!$('borough').value||r.borough===$('borough').value)&&(!$('status').value||r.status===$('status').value)&&(!$('from').value||r.created_date.slice(0,10)>=$('from').value)&&(!$('to').value||r.created_date.slice(0,10)<=$('to').value)&&(!q||[r.incident_address,r.incident_zip,r.complaint_type,r.descriptor,r.unique_key].join(' ').toLowerCase().includes(q)));$('count').textContent=filtered.length.toLocaleString();$('total').textContent=filtered.length.toLocaleString();$('closed').textContent=filtered.filter(r=>r.status==='Closed').length.toLocaleString();$('types').textContent=new Set(filtered.map(r=>r.complaint_type)).size;$('categories').innerHTML=groups.map(g=>`<button class="chip ${active===g[0]?'active':''}" data-category="${g[0]}" aria-pressed="${active===g[0]}"><i class="dot" style="--c:${g[2]}"></i>${g[1]}</button>`).join('');layer.clearLayers();markers.clear();filtered.forEach(r=>{const m=L.circleMarker([+r.latitude,+r.longitude],{radius:5,color:'#fff',weight:1.3,fillColor:color(r),fillOpacity:.82}).addTo(layer);m.bindTooltip(esc(r.complaint_type));m.on('click',()=>select(r));markers.set(r.unique_key,m)});list()}
function list(){const shown=filtered.slice(0,visible);$('reports').innerHTML=shown.length?shown.map(r=>`<button class="report ${selected===r.unique_key?'selected':''}" data-id="${esc(r.unique_key)}"><i class="dot" style="--c:${color(r)}"></i><div style="flex:1"><strong>${esc(r.complaint_type||'ไม่ระบุประเภท')}</strong><p>${esc(r.incident_address||r.borough||'ไม่ระบุที่อยู่')}</p><small>${esc(r.borough)} · ${esc(r.created_date.replace('T',' ').slice(5,16))} NYC</small><span class="status-label">${esc(r.status||'ไม่ระบุ')}</span></div></button>`).join('')+(filtered.length>visible?'<button id="more">แสดงเพิ่มอีก 40 รายงาน</button>':''):'<p class="empty">ไม่พบรายงานที่ตรงกับตัวกรอง<br>ลองล้างตัวกรองหรือเปลี่ยนคำค้นหา</p>'}
function select(r){selected=r.unique_key;map.flyTo([+r.latitude,+r.longitude],15,{duration:.6});$('detail').hidden=false;$('detail').innerHTML=`<button class="close" aria-label="ปิดรายละเอียด">×</button><div class="eyebrow">SERVICE REQUEST #${esc(r.unique_key)}</div><h3>${esc(r.complaint_type)}</h3><p>${esc(r.descriptor)}</p><dl><dt>ที่อยู่</dt><dd>${esc(r.incident_address||'ไม่ระบุ')}</dd><dt>เขต</dt><dd>${esc(r.borough)}</dd><dt>สถานะ</dt><dd>${esc(r.status)}</dd><dt>หน่วยงาน</dt><dd>${esc(r.agency_name||r.agency)}</dd><dt>รายงานเมื่อ</dt><dd>${esc(r.created_date.replace('T',' ').slice(0,19))} (NYC)</dd></dl><p>${esc(r.resolution_description||'ยังไม่มีรายละเอียดการดำเนินการ')}</p>`;$('detail').querySelector('.close').onclick=()=>{$('detail').hidden=true};list()}
$('categories').onclick=e=>{const b=e.target.closest('[data-category]');if(b){active=b.dataset.category;render()}};$('reports').onclick=e=>{const b=e.target.closest('[data-id]');if(b)select(filtered.find(r=>r.unique_key===b.dataset.id));if(e.target.id==='more'){visible+=40;list()}};['search','borough','status','from','to'].forEach(id=>$(id).addEventListener(id==='search'?'input':'change',render));$('reset').onclick=()=>{active='all';['search','borough','status','from','to'].forEach(id=>$(id).value='');render()};$('fit').onclick=()=>{if(filtered.length)map.fitBounds(filtered.map(r=>[+r.latitude,+r.longitude]),{padding:[60,100],maxZoom:15})};
function accept(rows,live){data=rows.filter(r=>Number.isFinite(+r.latitude)&&Number.isFinite(+r.longitude)&&+r.latitude>40&&+r.latitude<42&&+r.longitude>-75&&+r.longitude<-72).sort((a,b)=>b.created_date.localeCompare(a.created_date));options();render();$('data-state').textContent=(live?'โหลดจาก NYC Open Data แล้ว':'ข้อมูลจริงที่บันทึกไว้')+' · ล่าสุด '+(data[0]?.created_date.replace('T',' ').slice(0,16)||'—')+' NYC';$('scope').textContent=`ชุดข้อมูล ${data.length.toLocaleString()} รายงานที่มีพิกัด · ตัวกรองใช้กับชุดนี้ ไม่ใช่ทั้งเมือง`;}
$('refresh').onclick=async()=>{const b=$('refresh');b.disabled=true;b.textContent='กำลังโหลด…';try{const params=new URLSearchParams({'$limit':'2000','$where':'latitude IS NOT NULL AND longitude IS NOT NULL','$order':'created_date DESC'});const res=await fetch('https://data.cityofnewyork.us/resource/erm2-nwe9.json?'+params,{signal:AbortSignal.timeout(20000)});if(!res.ok)throw Error();const rows=await res.json();if(!Array.isArray(rows))throw Error();accept(rows,true)}catch{$('data-state').textContent='โหลดล่าสุดไม่สำเร็จ · ยังคงแสดงข้อมูลเดิม'}finally{b.disabled=false;b.textContent='↻ โหลดล่าสุด'}};
$('export').onclick=()=>{const keys=['unique_key','created_date','complaint_type','descriptor','status','borough','incident_address','latitude','longitude'];const csv='\ufeff'+[keys,...filtered.map(r=>keys.map(k=>{let v=String(r[k]??'');if(/^[=+@-]/.test(v))v="'"+v;return '"'+v.replace(/"/g,'""')+'"'}))].map(r=>r.join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='nyc-311-filtered.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
fetch('snapshot.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(rows=>accept(rows,false)).catch(()=>{$('data-state').textContent='ไม่สามารถโหลดข้อมูลได้ กรุณากดโหลดล่าสุด';$('reports').innerHTML='<p class="empty">โหลดข้อมูลไม่สำเร็จ</p>'});
